import {enhanceSelect} from './select-ui.mjs?v=2';
import{dayKey,minuteOf,taskBounds,currentTask,initialSeconds,progress,segmentSeconds,remainingSeconds,validateTask,stepSchedule,reconcileSteps,taskEmoji}from'./core.mjs?v=2';
const $=id=>document.getElementById(id), esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID(), KEY='ascend.v1';
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',checklist:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 2v4m8-4v4M8 13l3 3 5-6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 .5c0 2-2.5 2-2.5 4M12 17h.01"/>',settings:'<path d="m10 3-.6 2.5-2 .9L5 5.7 3 9l1.8 1.8v2.4L3 15l2 3.3 2.4-.7 2 .9L10 21h4l.6-2.5 2-.9 2.4.7 2-3.3-1.8-1.8v-2.4L21 9l-2-3.3-2.4.7-2-.9L14 3z"/><circle cx="12" cy="12" r="3"/>',left:'<path d="m14 7-5 5 5 5"/>',right:'<path d="m10 7 5 5-5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',play:'<path d="m9 5 11 7-11 7z"/>',pause:'<path d="M9 5v14M15 5v14"/>',volume:'<path d="m11 5-6 4H2v6h3l6 4zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
icons.expand='<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>';icons.stop='<rect x="6" y="6" width="12" height="12" rx="2"/>';
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.plus}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const emptyState=()=>({version:1,goals:[],tasks:[],sessions:[],history:{},selectedGoal:'',active:null,demo:false});
let state=emptyState(),storageError=false;
try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(validBackup(parsed))state={...emptyState(),...parsed};else storageError=true;}}catch{storageError=true;}
let selectedDate=dayKey(), prepared=null, detached=false, toastTimeout, detailTaskId=null;
function validBackup(s){return s&&s.version===1&&Array.isArray(s.goals)&&Array.isArray(s.tasks)&&Array.isArray(s.sessions)&&s.goals.every(g=>typeof g.id==='string'&&typeof g.name==='string')&&s.tasks.every(t=>typeof t.id==='string'&&typeof t.title==='string'&&typeof t.date==='string'&&typeof t.start==='string'&&typeof t.end==='string'&&['task','commitment'].includes(t.kind)&&Number.isFinite(taskBounds(t).start)&&minuteOf(t.end)>minuteOf(t.start)&&(!t.substeps||(Array.isArray(t.substeps)&&t.substeps.every(v=>typeof v.id==='string'&&typeof v.title==='string'))))&&s.sessions.every(v=>Number.isFinite(v.seconds)&&v.seconds>=0&&typeof v.date==='string')&&(!s.active||(typeof s.active.title==='string'&&Number.isFinite(s.active.remaining)&&Number.isFinite(s.active.elapsed)&&['running','paused','ended'].includes(s.active.status)&&Number.isFinite(s.active.endAt)));}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Unable to save in this browser. Download a backup from Settings.');}}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').hidden=true,4500);}
function goalName(id){return state.goals.find(g=>g.id===id)?.name||'General focus';}
function fmtTime(value){const[h,m]=value.split(':').map(Number);return`${h%12||12}${m?':'+String(m).padStart(2,'0'):''} ${h<12?'AM':'PM'}`;}
function niceDate(value,opts={month:'short',day:'numeric'}){return new Date(value+'T12:00:00').toLocaleDateString(undefined,opts);}
function options(selected,allText='No goal'){return`<option value="">${allText}</option>`+state.goals.map(g=>`<option value="${esc(g.id)}" ${g.id===selected?'selected':''}>${esc(g.name)}</option>`).join('');}
function snapshot(){const today=dayKey();state.history[today]=Object.fromEntries(['',...state.goals.map(g=>g.id)].map(id=>[id,progress(state.tasks,id).percent]));save();}
function render(){
  if(!state.goals.some(g=>g.id===state.selectedGoal))state.selectedGoal=state.goals[0]?.id||'';
  $('goalFilter').innerHTML=state.goals.length?state.goals.map(g=>`<option value="${esc(g.id)}" ${g.id===state.selectedGoal?'selected':''}>${esc(g.name)}</option>`).join(''):'<option value="" disabled selected>Choose a goal</option>';
  $('headerDate').textContent=niceDate(selectedDate,{weekday:'short',month:'short',day:'numeric'});
  $('todayButton').textContent=selectedDate===dayKey()?'Today':niceDate(selectedDate);
  renderTimeline();renderStats();renderFocus();
}
function renderTimeline(){if(detailTaskId&&state.tasks.some(t=>t.id===detailTaskId)){renderDetail();return;}detailTaskId=null;$('taskDetail').hidden=true;$('timelineScroll').hidden=false;$('addTask').hidden=false;document.querySelector('.schedule-footer').hidden=false;$('scheduleHeading').textContent='Your day';const tasks=state.tasks.filter(t=>t.date===selectedDate).sort((a,b)=>a.start.localeCompare(b.start));const startHour=Math.min(8,...tasks.map(t=>Math.floor(minuteOf(t.start)/60)));const endHour=Math.max(21,...tasks.map(t=>Math.ceil(minuteOf(t.end)/60)));const height=(endHour-startHour)*60;$('timeline').style.height=height+'px';let html='';for(let h=startHour;h<=endHour;h++)html+=`<span class="hour-label" style="top:${(h-startHour)*60}px">${h%12||12} ${h<12?'AM':'PM'}</span>`;
for(const t of tasks){const top=minuteOf(t.start)-startHour*60,duration=minuteOf(t.end)-minuteOf(t.start);html+=`<button class="task-block ${t.kind==='commitment'?'commitment':''} ${t.done?'done':''}" style="top:${top}px;height:${Math.max(duration-2,21)}px;left:3px;right:0" data-task="${esc(t.id)}" aria-label="${esc(t.title)}, ${fmtTime(t.start)} to ${fmtTime(t.end)}${t.done?', completed':''}">${duration>=35?`<span class="task-time">${fmtTime(t.start)} – ${fmtTime(t.end)}${t.done?' · ✓':''}</span>`:''}<span class="task-name">${esc(t.title)} <span class="task-emoji" aria-hidden="true">${taskEmoji(t.title,t.kind)}</span></span>${duration>=75&&t.step?`<span class="task-step">${esc(t.step)}</span>`:''}${duration>=100&&t.goalId?`<span class="task-goal">${esc(goalName(t.goalId))}</span>`:''}</button>`;}
const now=new Date(),nowMin=now.getHours()*60+now.getMinutes();if(selectedDate===dayKey()&&nowMin>=startHour*60&&nowMin<=endHour*60)html+=`<div class="now-line" style="top:${nowMin-startHour*60}px"><span>NOW ${fmtTime(`${now.getHours()}:${String(now.getMinutes()).padStart(2,'0')}`)}</span></div>`;
$('timeline').innerHTML=html;
$('timelineScroll').classList.toggle('is-empty',!tasks.length);$('timelineScroll').inert=!tasks.length;
$('emptyDay').hidden=!!tasks.length;
$('emptyDay').innerHTML=!tasks.length?`<span class="empty-symbol" aria-hidden="true">✳</span><h3>A little room to begin.</h3><button class="primary" id="emptyAddTask">Add a task</button>${!state.tasks.length?'<button class="text-button" id="emptySample">Explore a sample day</button>':''}`:'';
$('timeline').querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>zoomIntoTask(b));
if($('emptyAddTask'))$('emptyAddTask').onclick=()=>openTask();if($('emptySample'))$('emptySample').onclick=loadSample;
const mins=tasks.reduce((s,t)=>s+minuteOf(t.end)-minuteOf(t.start),0);$('scheduleSummary').textContent=tasks.length?`${tasks.length} ${tasks.length===1?'item':'items'} · ${Math.floor(mins/60)}h ${mins%60?mins%60+'m ':''}planned`:'';$('dayCaption').textContent=niceDate(selectedDate,{weekday:'long'});}

let zooming=false;
async function zoomIntoTask(button){
  if(zooming)return;zooming=true;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const calendar=$('timelineScroll'),rect=calendar.getBoundingClientRect(),target=button.getBoundingClientRect();
  if(!reduced){
    calendar.style.transformOrigin=`${target.left-rect.left+target.width/2}px ${target.top-rect.top+target.height/2}px`;
    await calendar.animate([{transform:'scale(1)',opacity:1},{transform:'scale(1.8)',opacity:0}],{duration:250,easing:'cubic-bezier(.4,0,.2,1)'}).finished;
  }
  detailTaskId=button.dataset.task;renderTimeline();$('taskDetail').scrollTop=0;
  if(!reduced)$('taskDetail').animate([{transform:'scale(.94)',opacity:0},{transform:'scale(1)',opacity:1}],{duration:220,easing:'cubic-bezier(.2,.8,.2,1)'});
  $('backToDay')?.focus({preventScroll:true});zooming=false;
}
function stepsFor(task){
  if(Array.isArray(task.substeps))return task.substeps;
  return task.step?[{id:task.id+'-first',title:task.step,done:!!task.done}]:[];
}
function minuteLabel(value){return `${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`;}
function renderDetail(){
  const task=state.tasks.find(t=>t.id===detailTaskId);if(!task){detailTaskId=null;renderTimeline();return;}
  $('timelineScroll').hidden=true;$('emptyDay').hidden=true;$('taskDetail').hidden=false;$('addTask').hidden=true;
  document.querySelector('.schedule-footer').hidden=true;$('scheduleHeading').textContent='Task breakdown';
  $('scheduleSummary').textContent=niceDate(task.date,{weekday:'short',month:'short',day:'numeric'});
  $('dayCaption').textContent=`${minuteOf(task.end)-minuteOf(task.start)} min`;
  const steps=stepSchedule({...task,substeps:stepsFor(task)}),count=steps.filter(s=>s.done).length;
  const totalMinutes=minuteOf(task.end)-minuteOf(task.start),pxPerMinute=Math.max(3,Math.min(10,420/totalMinutes));
  let rows='';
  for(const step of steps){
    const ticks=Array.from({length:step.minutes},(_,i)=>`<i class="minute-tick ${i%5===0?'major':''}" style="top:${i*pxPerMinute}px"></i>`).join('');
    rows+=`<div class="minute-step ${step.done?'completed':''}" style="min-height:${Math.max(step.minutes*pxPerMinute,80)}px"><div class="minute-scale"><time>${minuteLabel(step.startMinute)}</time>${ticks}</div><label class="substep-card"><input type="checkbox" data-step="${esc(step.id)}" ${step.done?'checked':''}><span><strong>${esc(step.title)}</strong><small>${step.minutes} min · ${minuteLabel(step.startMinute)}–${minuteLabel(step.endMinute)}</small></span></label></div>`;
  }
  $('taskDetail').innerHTML=`<div class="detail-toolbar"><button class="text-button" id="backToDay">${icon('left')}Back to day</button><button class="secondary small-button" id="editDetail">Edit task</button></div><div class="detail-heading"><h2>${esc(task.title)} <span aria-hidden="true">${taskEmoji(task.title,task.kind)}</span></h2><p>${fmtTime(task.start)} – ${fmtTime(task.end)}${task.goalId?' · '+esc(goalName(task.goalId)):''}</p></div>${steps.length?`<div class="detail-progress"><span>${count} of ${steps.length} substeps</span><div><i style="width:${count/steps.length*100}%"></i></div></div><div class="minute-timeline">${rows}<time class="end-time">${minuteLabel(minuteOf(task.end))}</time></div>`:`<div class="detail-empty"><p>${task.kind==='commitment'?'Time reserved.':'Break this task into smaller steps.'}</p>${task.kind==='task'?'<button class="secondary" id="addSubsteps">Add substeps</button>':''}</div>`}<div class="detail-actions">${task.kind==='task'?`<button class="primary" id="detailFocus" ${task.done?'disabled':''}>Focus on task</button><button class="secondary" id="detailComplete">${task.done?'Reopen task':'Mark complete'}</button>`:''}</div>`;
  $('backToDay').onclick=()=>{detailTaskId=null;renderTimeline();};$('editDetail').onclick=()=>openTask(task.id);
  if($('addSubsteps'))$('addSubsteps').onclick=()=>{openTask(task.id);$('taskSteps').focus();};
  $('taskDetail').querySelectorAll('[data-step]').forEach(input=>input.onchange=()=>{task.substeps=stepsFor(task).map(step=>step.id===input.dataset.step?{...step,done:input.checked}:step);task.step=task.substeps.find(step=>!step.done)?.title||'';if(!input.checked)task.done=false;if(prepared?.taskId===task.id)prepared.step=task.step;if(state.active?.taskId===task.id)state.active.step=task.step;snapshot();const scroll=$('taskDetail').scrollTop;renderDetail();$('taskDetail').scrollTop=scroll;renderFocus();renderStats();$('taskDetail').querySelector(`[data-step="${CSS.escape(input.dataset.step)}"]`)?.focus({preventScroll:true});});
  if($('detailFocus'))$('detailFocus').onclick=()=>{if(state.active){toast('Finish your current session first.');return;}prepared={taskId:task.id,goalId:task.goalId,title:task.title,step:task.step,remaining:initialSeconds(task),scheduled:true};detached=false;if(task.goalId){state.selectedGoal=task.goalId;save();render();}else renderFocus();document.querySelector('.focus-card').scrollIntoView({behavior:'smooth',block:'nearest'});};
  if($('detailComplete'))$('detailComplete').onclick=()=>{if(state.active?.taskId===task.id){endCheckIn();return;}task.done=!task.done;if(task.done)task.substeps=stepsFor(task).map(step=>({...step,done:true}));snapshot();renderDetail();renderStats();renderFocus();};
}
function renderStats(){const id=state.selectedGoal,p=id?progress(state.tasks,id):{total:0,complete:0,percent:0},sessions=state.sessions.filter(s=>id&&s.goalId===id);let seconds=sessions.reduce((a,s)=>a+s.seconds,0);if(state.active&&id&&state.active.goalId===id)seconds+=state.active.elapsed+segmentSeconds(state.active);const hours=seconds/3600;$('hoursValue').innerHTML=`${hours===0?'0':hours<.1?'<0.1':hours.toFixed(1).replace(/\.0$/,'')}<span>h</span>`;$('hoursGoal').textContent=id?goalName(id):'your goals';const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {label:d.toLocaleDateString(undefined,{weekday:'short'}),minutes:Math.round(sessions.filter(s=>s.date===dayKey(d)).reduce((n,s)=>n+s.seconds,0)/60)};});const peak=Math.max(30,...week.map(d=>d.minutes));$('focusWeek').innerHTML=week.map(d=>`<div title="${d.label}: ${d.minutes} minutes"><i style="height:${Math.max(3,d.minutes/peak*100)}%"></i><span>${d.label[0]}</span></div>`).join('');$('sessionsCount').textContent=sessions.length?`${sessions.length} ${sessions.length===1?'session':'sessions'}`:'0 sessions';$('progressPercent').innerHTML=`${p.percent}<span>%</span>`;$('progressLabel').textContent=p.total?`${p.complete} of ${p.total} tasks completed`:'No tasks yet';$('progressDetail').textContent=id?goalName(id):'Choose a goal';
const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return{key:dayKey(d),label:d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,1)};});const vals=days.map(d=>state.history[d.key]?.[id]??null);vals[6]=p.percent;let carry=null;const points=vals.map((v,i)=>{if(v!==null)carry=v;return carry===null?null:{x:i*40+4,y:66-carry*.58};});const known=points.filter(Boolean);const line=known.map((v,i)=>`${i?'L':'M'}${v.x},${v.y}`).join(' ');const area=known.length?`${line} L${known.at(-1).x},70 L${known[0].x},70Z`:'';$('chartWrap').innerHTML=`<svg viewBox="0 0 248 74" role="img" aria-label="Goal completion over the last seven days; today's progress is ${p.percent} percent"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#df8dbb" stop-opacity=".2"/><stop offset="100%" stop-color="#df8dbb" stop-opacity=".02"/></linearGradient></defs><path d="M4 8H244 M4 37H244 M4 66H244" stroke="#f3eef1" stroke-width="1"/><path d="${area}" fill="url(#chartFill)"/><path d="${line}" fill="none" stroke="#cf5597" stroke-width="1.8"/>${known.map(v=>`<circle cx="${v.x}" cy="${v.y}" r="2.5" fill="white" stroke="#cf5597" stroke-width="1.4"/>`).join('')}</svg><div class="chart-labels">${days.map(d=>`<span>${d.label}</span>`).join('')}</div>`;}
function selection(){if(state.active)return state.active;if(prepared)return prepared;if(!detached){const t=currentTask(state.tasks);if(t)return{taskId:t.id,goalId:t.goalId,title:t.title,step:t.step,remaining:initialSeconds(t),total:initialSeconds(t),scheduled:true};}return null;}
function renderFocus(){const s=selection(),active=state.active;const secs=s?(active?remainingSeconds(active):s.remaining):1500;$('focusHeading').textContent=s?`${s.title} ${taskEmoji(s.title)}`:'Your next session';$('focusContext').textContent=s?(s.step||(s.taskId?'Scheduled task':'Independent session')):'';$('timer').textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;$('timerCaption').textContent=active?(active.status==='running'?'FOCUSING':active.status==='ended'?'FINISHED':'PAUSED'):s?.taskId?'READY':'MINUTES';$('timerRing').classList.toggle('running',active?.status==='running');$('timerRing').classList.toggle('paused',active?.status==='paused');updateTimerVisual(secs,active?.total||s?.remaining||1500);$('immersivePause').textContent=active?.status==='paused'?'Resume':'Pause';
$('timerActions').innerHTML=active?(active.status==='ended'?'<button class="primary" id="checkIn">Check in</button>':`<button class="primary" id="pauseTimer">${active.status==='running'?'Pause':'Resume'}</button><button class="secondary" id="finishTimer">Finish</button>`):'<button class="primary" id="startTimer">Start session</button>';
$('focusSecondary').innerHTML=active&&active.status!=='ended'?'<button id="enterFocus">Enter focus view</button>':active?'':`<button id="independentButton">Independent session</button>${detached||prepared?'<button id="followSchedule">Follow schedule</button>':''}`;for(const [id,name] of [['startTimer','play'],['pauseTimer',active?.status==='running'?'pause':'play'],['finishTimer','stop'],['checkIn','checklist'],['enterFocus','expand'],['independentButton','plus'],['followSchedule','calendar']]){const button=$(id);if(button)button.innerHTML=icon(name)+'<span>'+button.textContent+'</span>';}if($('enterFocus'))$('enterFocus').onclick=()=>enterFocus();if($('startTimer'))$('startTimer').onclick=startTimer;if($('pauseTimer'))$('pauseTimer').onclick=togglePause;if($('finishTimer'))$('finishTimer').onclick=()=>endCheckIn();if($('checkIn'))$('checkIn').onclick=()=>showFinish();if($('independentButton'))$('independentButton').onclick=openIndependent;if($('followSchedule'))$('followSchedule').onclick=()=>{prepared=null;detached=false;renderFocus();};}
function startTimer(){const origin=$('startTimer')?.getBoundingClientRect();let s=selection();if(!s){openIndependent();return;}const now=Date.now();state.active={...s,id:uid(),date:dayKey(),remaining:s.remaining,total:s.remaining,elapsed:0,status:'running',runningSince:now,endAt:now+s.remaining*1000};prepared=null;save();renderFocus();enterFocus(origin);}
function accrue(){const s=state.active;if(!s||s.status!=='running')return;s.elapsed+=segmentSeconds(s);s.remaining=remainingSeconds(s);s.runningSince=null;}
function togglePause(){const s=state.active;if(!s)return;if(s.status==='running'){accrue();s.status='paused';}else{const now=Date.now();s.status='running';s.runningSince=now;s.endAt=now+s.remaining*1000;}save();renderFocus();}
function endCheckIn(){if(!state.active)return;accrue();state.active.status='ended';save();renderFocus();showFinish();}
function showFinish(){leaveFocus();const s=state.active;if(!s)return;$('finishMessage').textContent=`You spent ${Math.max(0,Math.round(s.elapsed/60))} ${Math.round(s.elapsed/60)===1?'minute':'minutes'} on “${s.title}”. ${s.taskId?'How did it go?':'Every bit of focus counts.'}`;$('markComplete').hidden=!s.taskId;$('saveProgress').textContent=s.taskId?'Save session · more to do':'Save session';if(!$('finishDialog').open)$('finishDialog').showModal();}
function logSession(complete=false){const s=state.active;if(!s)return;accrue();if(s.elapsed>0)state.sessions.push({id:s.id,taskId:s.taskId||null,goalId:s.goalId||'',title:s.title,date:s.date,seconds:Math.round(s.elapsed),endedAt:Date.now()});if(complete){const task=state.tasks.find(t=>t.id===s.taskId);if(task){task.done=true;task.substeps=stepsFor(task).map(step=>({...step,done:true}));task.completedAt=Date.now();}}state.active=null;prepared=null;detached=false;snapshot();$('finishDialog').close();render();toast(complete?'One more step forward. Task completed.':'Your focus time is saved.');}
function openTask(id){const task=state.tasks.find(t=>t.id===id);$('taskForm').reset();$('taskError').textContent='';$('taskId').value=task?.id||'';$('taskDialogTitle').textContent=task?'Edit scheduled task':'Plan a task';$('taskTitle').value=task?.title||'';$('taskKind').value=task?.kind||'task';$('completionLabel').hidden=!task||task.kind!=='task';$('taskDone').checked=task?.done||false;$('taskGoal').innerHTML=options(task?.goalId??state.selectedGoal);$('taskSteps').value=(task?stepsFor(task):[]).map(x=>x.title).join('\n');$('substepsLabel').hidden=task?.kind==='commitment';$('taskDate').value=task?.date||selectedDate;const now=new Date();const h=Math.min(22,now.getHours()+1);$('taskStart').value=task?.start||`${String(h).padStart(2,'0')}:00`;$('taskEnd').value=task?.end||`${String(h).padStart(2,'0')}:30`;$('deleteTask').hidden=!task;$('focusTask').hidden=!task||task.kind!=='task'||task.done;$('taskGoal').disabled=$('taskKind').value==='commitment';$('taskDialog').showModal();}
$('taskKind').onchange=()=>{$('substepsLabel').hidden=$('taskKind').value==='commitment';$('taskGoal').disabled=$('taskKind').value==='commitment';$('completionLabel').hidden=!$('taskId').value||$('taskKind').value!=='task';};
$('taskForm').onsubmit=e=>{e.preventDefault();const id=$('taskId').value;const prior=state.tasks.find(t=>t.id===id);if(state.active?.taskId===id){$('taskError').textContent='Finish the active focus session before editing this task.';return;}const task={...prior,id:id||uid(),title:$('taskTitle').value.trim(),kind:$('taskKind').value,goalId:$('taskKind').value==='commitment'?'':$('taskGoal').value,step:'',substeps:[],date:$('taskDate').value,start:$('taskStart').value,end:$('taskEnd').value,done:$('taskKind').value==='task'&&$('taskDone').checked};const titles=$('taskSteps').value.split('\n').map(v=>v.trim()).filter(Boolean);if(task.kind==='task'&&titles.length>minuteOf(task.end)-minuteOf(task.start)){$('taskError').textContent='Allow at least one minute per substep.';return;}task.substeps=task.kind==='task'?reconcileSteps(prior?stepsFor(prior):[],titles,uid):[];task.step=task.substeps.find(v=>!v.done)?.title||'';const error=validateTask(task,state.tasks);if(error){$('taskError').textContent=error;return;}if(prior)state.tasks=state.tasks.map(t=>t.id===id?task:t);else state.tasks.push(task);if(prepared?.taskId===id)prepared=null;selectedDate=task.date;snapshot();$('taskDialog').close();render();toast(prior?'Task updated.':'Task added.');};
$('deleteTask').onclick=()=>{const id=$('taskId').value;if(state.active?.taskId===id){$('taskError').textContent='Finish the active focus session before deleting this task.';return;}if(!confirm('Delete this task? Logged focus time will be kept.'))return;state.tasks=state.tasks.filter(t=>t.id!==id);if(prepared?.taskId===id)prepared=null;snapshot();$('taskDialog').close();render();toast('Task removed.');};
$('focusTask').onclick=()=>{if(state.active){$('taskError').textContent='Finish your current focus session before switching tasks.';return;}const t=state.tasks.find(t=>t.id===$('taskId').value);prepared={taskId:t.id,goalId:t.goalId,title:t.title,step:t.step,remaining:initialSeconds(t),scheduled:true};detached=false;$('taskDialog').close();renderFocus();document.querySelector('.focus-card').scrollIntoView({behavior:'smooth',block:'center'});};
function openGoals(){$('goalsList').innerHTML=state.goals.length?state.goals.map(g=>{const p=progress(state.tasks,g.id);return`<div class="goal-row ${state.selectedGoal===g.id?'selected':''}"><div><strong>${esc(g.name)}</strong><p>${p.complete} of ${p.total} planned steps completed</p></div><button data-select-goal="${esc(g.id)}">${state.selectedGoal===g.id?'Selected':'Select'}</button></div>`;}).join(''):'<p class="dialog-description">Your first goal starts here.</p>';$('goalsList').querySelectorAll('[data-select-goal]').forEach(b=>b.onclick=()=>{state.selectedGoal=b.dataset.selectGoal;save();render();$('goalsDialog').close();});if(!$('goalsDialog').open)$('goalsDialog').showModal();}
$('goalForm').onsubmit=e=>{e.preventDefault();const name=$('goalName').value.trim();if(!name)return;if(state.goals.some(g=>g.name.toLowerCase()===name.toLowerCase())){toast('That goal already exists.');return;}const g={id:uid(),name,createdAt:Date.now()};state.goals.push(g);state.selectedGoal=g.id;$('goalForm').reset();snapshot();render();openGoals();toast('Goal added.');};
$('goalFilter').onchange=e=>{state.selectedGoal=e.target.value;save();renderStats();};
function openIndependent(){if(state.active){toast('Finish your current session first.');return;}$('independentTitle').value='';$('independentGoal').innerHTML=options(state.selectedGoal);$('independentDialog').showModal();}
$('independentForm').onsubmit=e=>{e.preventDefault();const mins=Number($('independentMinutes').value),title=$('independentTitle').value.trim();if(!title||mins<1||mins>240)return;prepared={taskId:null,goalId:$('independentGoal').value,title,remaining:mins*60};detached=true;$('independentDialog').close();renderFocus();toast('Your independent session is ready.');};
$('markComplete').onclick=()=>logSession(true);$('saveProgress').onclick=()=>logSession(false);$('extendSession').onclick=()=>{const s=state.active;if(!s)return;const now=Date.now();s.remaining=300;s.total+=300;s.runningSince=now;s.endAt=now+300000;s.status='running';save();$('finishDialog').close();renderFocus();};
$('finishDialog').addEventListener('cancel',e=>{e.preventDefault();$('finishDialog').close();});
function moveDay(delta){detailTaskId=null;const d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()+delta);selectedDate=dayKey(d);render();}
$('prevDay').onclick=()=>moveDay(-1);$('nextDay').onclick=()=>moveDay(1);$('todayButton').onclick=$('todayNav').onclick=()=>{selectedDate=dayKey();detailTaskId=null;render();};$('addTask').onclick=$('planningNav').onclick=()=>openTask();$('goalsNav').onclick=openGoals;$('settingsNav').onclick=()=>$('settingsDialog').showModal();$('helpNav').onclick=()=>$('helpDialog').showModal();document.querySelector('.wordmark').onclick=e=>{e.preventDefault();selectedDate=dayKey();detailTaskId=null;render();};document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
function loadSample(){if(state.active){toast('Finish your focus session first.');return;}if(state.tasks.length||state.goals.length){toast('A sample day is available in an empty workspace. Export your data before resetting.');return;}const today=dayKey(),g1={id:uid(),name:'Build my design career'},g2={id:uid(),name:'Make time for myself'};state.goals=[g1,g2];state.selectedGoal=g1.id;state.demo=true;const samples=[['09:00','09:30','Set the day in motion','Pick three things that matter today','task',g1.id,true],['10:00','12:00','Job search','Find three roles and tailor one application','task',g1.id,false],['12:30','13:30','Lunch & a little fresh air','','commitment','',false],['14:00','15:00','Explore portfolio ideas','Sketch three directions for a case study','task',g1.id,false],['17:30','18:30','Workout · push day','Show up. Start with the warm-up.','task',g2.id,false]];state.tasks=samples.map(([start,end,title,step,kind,goalId,done])=>({id:uid(),date:today,start,end,title,step,kind,goalId,done}));state.tasks.forEach(t=>{const titles=t.title==='Job search'?['Find three roles','Tailor my resume','Send applications']:t.title==='Explore portfolio ideas'?['Collect references','Sketch three directions','Choose a direction']:t.step?[t.step]:[];t.substeps=titles.map(title=>({id:uid(),title,done:t.done}));});state.sessions=[{id:uid(),date:today,title:'Set the day in motion',goalId:g1.id,seconds:1500}];snapshot();selectedDate=today;$('settingsDialog').close();render();toast("You're exploring a sample day.");}
$('sampleDay').onclick=loadSample;
function reset(){state=emptyState();detailTaskId=null;prepared=null;detached=false;selectedDate=dayKey();save();document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();toast('A fresh start.');}
$('resetData').onclick=()=>{if(confirm('Delete all goals, tasks, and focus history in this browser? Download a backup first if you want to keep them.'))reset();};
$('exportData').onclick=()=>{const copy=structuredClone(state);if(copy.active){copy.active.elapsed+=segmentSeconds(copy.active);copy.active.remaining=remainingSeconds(copy.active);copy.active.runningSince=null;copy.active.status='paused';}const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ascend-backup-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded.');};
$('importData').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const data=JSON.parse(await f.text());if(!validBackup(data))throw Error();if(!confirm('Replace this browser’s data with the backup?'))return;state={...emptyState(),...data};state.history=state.history&&typeof state.history==='object'?state.history:{};prepared=null;detached=false;save();render();$('settingsDialog').close();toast('Backup restored.');}catch{toast('This file is not a valid Ascend backup.');}finally{e.target.value='';}};
let audioContext=null,audioSource=null,audioGain=null,audioFilter=null,lfo=null,lfoGain=null,audioPlaying=false;
async function playSound(){try{if(!audioContext)audioContext=new(window.AudioContext||window.webkitAudioContext)();await audioContext.resume();if(audioSource){audioSource.stop();audioSource.disconnect();}if(lfo){lfo.stop();lfo.disconnect();lfo=null;}if(audioGain)audioGain.disconnect();if(audioFilter)audioFilter.disconnect();if(lfoGain)lfoGain.disconnect();const type=$('soundType').value,rate=audioContext.sampleRate,buffer=audioContext.createBuffer(1,rate*8,rate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){const white=Math.random()*2-1;if(type==='rain')data[i]=white*.35;else{last=(last+.02*white)/1.02;data[i]=last*3.5;}}audioSource=audioContext.createBufferSource();audioSource.buffer=buffer;audioSource.loop=true;audioFilter=audioContext.createBiquadFilter();audioFilter.type='lowpass';audioFilter.frequency.value=type==='rain'?2800:type==='ocean'?700:450;audioGain=audioContext.createGain();audioGain.gain.value=Number($('volume').value)/100*.6;audioSource.connect(audioFilter).connect(audioGain).connect(audioContext.destination);if(type==='ocean'){lfo=audioContext.createOscillator();lfo.frequency.value=.12;lfoGain=audioContext.createGain();lfoGain.gain.value=Number($('volume').value)/100*.25;lfo.connect(lfoGain).connect(audioGain.gain);lfo.start();}audioSource.start();audioPlaying=true;renderMusic();}catch{toast('Audio could not start. Try again in a supported browser.');}}
function renderMusic(){$('musicPlay').innerHTML=icon(audioPlaying?'pause':'play');$('musicPlay').setAttribute('aria-label',audioPlaying?'Pause ambient sound':'Play ambient sound');$('soundStatus').textContent=audioPlaying?'PLAYING':'OFF';$('albumArt').classList.toggle('playing',audioPlaying);}
$('musicPlay').onclick=()=>{if(audioPlaying){audioContext.suspend();audioPlaying=false;renderMusic();}else playSound();};$('soundType').onchange=()=>{if(audioPlaying)playSound();};$('volume').oninput=e=>{const v=Number(e.target.value)/100;if(audioGain)audioGain.gain.setTargetAtTime(v*.6,audioContext.currentTime,.1);if(lfoGain)lfoGain.gain.setTargetAtTime(v*.25,audioContext.currentTime,.1);};
let lastMinute='',lastTaskId='',lastDay=dayKey();function tick(){rotateCopy();const now=new Date(),minute=now.toISOString().slice(0,16);if(lastMinute!==minute){if(lastDay!==dayKey()){if(selectedDate===lastDay)selectedDate=dayKey();lastDay=dayKey();}lastMinute=minute;renderTimeline();renderStats();}if(state.active?.status==='running'){if(remainingSeconds(state.active)===0){endCheckIn();}else{const seconds=remainingSeconds(state.active);updateTimerVisual(seconds,state.active.total);$('timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}}else if(!state.active&&!prepared&&!detached){const current=currentTask(state.tasks);if(current?.id!==lastTaskId){lastTaskId=current?.id;renderFocus();}else if(current){const s=initialSeconds(current);$('timer').textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}}}
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const incoming=JSON.parse(e.newValue);if(validBackup(incoming)){state={...emptyState(),...incoming};render();toast('Updated from another Ascend tab.');}}catch{}}});document.addEventListener('visibilitychange',()=>{if(!document.hidden){tick();renderFocus();}});
const quotes=["Make room for progress.","One small step is still a step forward.","Give this moment your attention.","Start where you are. Keep moving.","Progress grows with practice.","You don’t need to do it all today.","A little focus. A little closer.","Let the next step be enough."];
const headlines=['Make room for <em>progress.</em>','A little closer to <em>your goal.</em>','Small steps. Real <em>momentum.</em>','Give your goals a little <em>space.</em>'];
let copySlot=-1;
function rotateCopy(){const slot=Math.floor(Date.now()/180000);if(slot===copySlot)return;copySlot=slot;const quote=quotes[slot%quotes.length];$('quote').textContent=quote;$('immersiveQuote').textContent=quote;}
function updateTimerVisual(seconds,total){const ratio=Math.max(0,Math.min(1,seconds/Math.max(1,total)));$('timerRing').style.setProperty('--remaining',ratio);$('immersiveRing').style.setProperty('--remaining',ratio);$('immersiveTimer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
let focusReturn=null;
function enterFocus(origin){if(!state.active||state.active.status==='ended')return;focusReturn=document.activeElement;const screen=$('focusScreen');screen.hidden=false;document.querySelector('.app-shell').inert=true;document.body.classList.add('immersed');const x=origin?origin.left+origin.width/2:innerWidth/2,y=origin?origin.top+origin.height/2:innerHeight/2;const radius=Math.hypot(Math.max(x,innerWidth-x),Math.max(y,innerHeight-y));if(!matchMedia('(prefers-reduced-motion: reduce)').matches)screen.animate([{clipPath:`circle(0px at ${x}px ${y}px)`},{clipPath:`circle(${radius}px at ${x}px ${y}px)`}],{duration:650,easing:'cubic-bezier(.22,.8,.2,1)'});$('immersivePause').focus({preventScroll:true});}
function leaveFocus(){if($('focusScreen').hidden)return;$('focusScreen').hidden=true;document.querySelector('.app-shell').inert=false;document.body.classList.remove('immersed');if(focusReturn?.isConnected)focusReturn.focus({preventScroll:true});else $('pauseTimer')?.focus({preventScroll:true});}
$('leaveFocus').onclick=leaveFocus;$('immersivePause').onclick=togglePause;$('immersiveFinish').onclick=endCheckIn;
$('focusScreen').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();leaveFocus();}if(e.key==='Tab'){const buttons=[$('leaveFocus'),$('immersivePause'),$('immersiveFinish')];const index=buttons.indexOf(document.activeElement);if((e.shiftKey&&index===0)||(!e.shiftKey&&index===2)){e.preventDefault();buttons[e.shiftKey?2:0].focus();}}});
document.querySelectorAll('select').forEach(select=>enhanceSelect(select,select.id==='goalFilter'?{footerLabel:'Manage goals',onFooter:openGoals}:{}));
$('pageHeadline').innerHTML=headlines[Math.floor(Math.random()*headlines.length)];rotateCopy();render();if(state.active?.status==='ended')showFinish();tick();setInterval(tick,1000);if(state.demo)toast("You're exploring a sample day.");if(storageError)toast('Saved data could not be read. Your previous storage has not been overwritten.');
